function renderProfile(){
 const saved=state.items.filter(x=>x.saved).length+state.biz.filter(x=>x.saved).length+(state.myBiz?.saved?1:0),mine=state.items.filter(x=>x.mine),groups=state.groups.filter(g=>g.on);
 return `<div class="page-head"><h1>Você</h1>${iconBtn('settings','settings','','Configurações')}</div><div class="profile-box"><span class="avatar me">${esc(initals(state.profile.name))}</span><div><h2>${esc(state.profile.name)}</h2><p class="small">${esc({ativa:'Militar da ativa',veterano:'Veterano',pensionista:'Pensionista militar',familia:'Família de militar'}[state.profile.role])} · ${esc(state.profile.force)}</p><p class="small" style="margin-top:6px">${state.profile.verified?'Perfil de teste verificado':'Verificação de teste pendente'}</p></div></div><div class="profile-grid"><button type="button" class="profile-stat" data-action="saved"><b>${saved}</b><span>salvos</span></button><button type="button" class="profile-stat" data-action="my-ads"><b>${mine.filter(x=>x.status==='active').length}</b><span>anúncios ativos</span></button><button type="button" class="profile-stat" data-action="my-questions"><b>${state.asks.filter(q=>q.mine).length}</b><span>suas perguntas</span></button><button type="button" class="profile-stat" data-action="groups"><b>${groups.length}</b><span>grupos</span></button></div><section class="section"><div class="list">${profileRow('swap_horiz','Seu momento',`${{moro:'Mora em',chegando:'Chegando a',saindo:'Saindo de'}[state.mode]} ${state.homeCity}`,'city')}${profileRow('sell','Meus anúncios',`${mine.length} publicados · ${state.drafts.length} rascunhos`,'my-ads')}${profileRow('notifications','Alertas de busca',(state.alerts||[]).length?`${(state.alerts||[]).length} ${(state.alerts||[]).length===1?'alerta':'alertas'} · ${(state.alerts||[]).filter(a=>a.notify).length} com avisos ligados`:'Filtre imóveis ou desapegos e toque em Avise-me','search-alerts')}${profileRow('build','Pedidos de serviço',`${requestList().filter(r=>r.mine&&requestActive(r)).length} abertos${state.myBiz?.live?` · ${providerRequests().length} para o seu negócio`:''}`,'requests')}${profileRow('bookmark','Salvos','Anúncios e negócios em uma lista','saved')}${profileRow('forum','Minhas perguntas e indicações','Acompanhe respostas e o que você resolveu','my-questions')}${profileRow('storefront',state.myBiz?.live?'Meu negócio':'Criar página do negócio',state.myBiz?.name||'Ofereça seus serviços à comunidade','my-biz')}${profileRow('family_restroom','Família convidada',`${state.invites.length} convites criados`,'family')}</div></section><section class="section">${sectionTitle('Avisos')}<div class="list">${pushRowHtml()}${installRowHtml()}<div class="list-row"><span class="txt"><b>Resumo diário</b><small>Preferência guardada no seu perfil de teste.</small></span><md-switch id="digest-switch" ${state.prefs.digest?'selected':''} aria-label="Resumo diário"></md-switch></div><div class="list-row"><span class="txt"><b>Avisos imediatos</b><small>Até ${state.prefs.cap} por dia</small></span>${iconBtn('remove','cap','-1','Diminuir limite de avisos')}${iconBtn('add','cap','1','Aumentar limite de avisos')}</div></div></section><section class="section"><div class="list">${profileRow('tune','Controles do protótipo','Cenários, cadastro, cidade inicial e respostas de teste','prototype')}</div></section>`;
}
function profileRow(ic,title,sub,action,value=''){return `<button type="button" class="list-row" data-action="${action}" data-value="${esc(value)}">${icon(ic)}<span class="txt"><b>${esc(title)}</b><small>${esc(sub)}</small></span>${icon('chevron_right')}</button>`;}
function renderSaved(){const items=state.items.filter(x=>x.saved),biz=[...state.biz,...(state.myBiz?.live?[state.myBiz]:[])].filter(x=>x.saved),visible=(savedType==='biz'?0:items.length)+(savedType==='items'?0:biz.length);return `<div class="page-head"><div><h1>Salvos</h1><p>Anúncios e negócios que você quer consultar de novo.</p></div></div>${filterChips([['all','Tudo'],['items','Anúncios'],['biz','Negócios']],savedType,'saved-filter')}${savedType!=='biz'&&items.length?`<section class="section">${sectionTitle('Anúncios')}${compareEntryHtml()}<div class="card-grid">${items.map(photoCard).join('')}</div></section>`:''}${savedType!=='items'&&biz.length?`<section class="section">${sectionTitle('Negócios')}<div class="card-grid">${biz.map(businessCard).join('')}</div></section>`:''}${!visible?empty(savedType==='items'?'Nenhum anúncio salvo':savedType==='biz'?'Nenhum negócio salvo':'Seus salvos aparecem aqui','Toque no marcador de um anúncio ou negócio para guardar.', 'bookmark_border',savedType==='biz'?'businesses':'catalog-all',savedType==='biz'?'Explorar negócios':'Explorar anúncios'):''}`;}
function renderMyAds(){const all=state.items.filter(x=>x.mine&&x.city===state.homeCity),items=all.filter(x=>x.status===myAdsFilter);let h=`<div class="page-head"><div><h1>Meus anúncios</h1><p>Publique, acompanhe contatos e encerre suas ofertas.</p></div>${btn('Anunciar','create','','tonal','add')}</div>${filterChips([['active','Ativos'],['sold','Encerrados'],['drafts','Rascunhos']],myAdsFilter,'my-ads-filter')}`;if(myAdsFilter==='drafts'){return h+(state.drafts.length?`<div class="list">${state.drafts.map(d=>`<div class="list-row"><button type="button" class="txt" data-action="open-draft" data-value="${d.id}"><b>${esc(d.title||'Anúncio sem título')}</b><small>${d.kind==='imovel'?'Imóvel':'Desapego'} · rascunho</small></button>${iconBtn('delete','delete-draft',d.id,'Excluir rascunho')}</div>`).join('')}</div>`:empty('Nenhum rascunho','Use “Salvar rascunho” enquanto prepara um anúncio.','edit_note','create-item','Preparar anúncio'));}return h+(items.length?`<div class="card-grid">${items.map(i=>`<div>${photoCard(i)}<div class="card-buttons">${btn('Editar','edit-item',i.id,'text','edit')}${btn(i.status==='sold'?'Reativar':'Encerrar','item-status',i.id,'text',i.status==='sold'?'refresh':'check')}${iconBtn('delete','delete-item',i.id,'Excluir anúncio')}</div></div>`).join('')}</div>`:empty(myAdsFilter==='active'?'Nenhum anúncio ativo':'Nenhum anúncio encerrado','Suas publicações aparecem nesta lista.','sell',myAdsFilter==='active'?'create-item':'my-ads-filter',myAdsFilter==='active'?'Criar anúncio':'Ver anúncios ativos').replace('data-action="my-ads-filter"','data-action="my-ads-filter" data-value="active"'));}
function renderMineQuestions(){const qs=state.asks.filter(q=>q.city===state.homeCity&&(q.mine||q.answers.some(a=>a.mine)));return `<div class="page-head"><div><h1>Minhas perguntas e indicações</h1><p>Seu histórico de participação na comunidade.</p></div>${btn('Perguntar','ask','','tonal','add')}</div>${qs.length?`<div class="list">${qs.map(questionRow).join('')}</div>`:empty('Seu histórico começa aqui','Uma dúvida sua pode virar uma resposta útil para outras famílias.','forum','ask','Pedir indicação')}`;}
